use super::*;

/// Whether PHP 8.5's `date_create()` accepts each string, generated by
/// running it.
const CASES: &[(&str, bool)] = &[
    ("now", true),
    ("4 qm", false),
    ("202/20", false),
    ("foo", false),
    ("bar", false),
    ("qm", false),
    ("2020-10-12", true),
    ("2020-13-01", false),
    ("2020-02-31", true),
    ("2020-10-12T25:00", false),
    ("next monday", true),
    ("last day of next month", true),
    ("first monday of January 2020", true),
    ("+2 days", true),
    ("-1 week 2 days ago", true),
    ("3 hours ago", true),
    ("tomorrow noon", true),
    ("noon tomorrow", true),
    ("10am 11am", false),
    ("10:00 monday", true),
    ("monday 10:00", true),
    ("yesterday 10:00 10:00", false),
    ("1030 1030", true),
    ("1030 1030 1030", false),
    ("2020-01-01 2021-01-01", false),
    ("CET", true),
    ("CET CET", true),
    ("CET CET CET", false),
    ("Foo", false),
    ("second", false),
    ("first", false),
    ("1 µs", true),
    ("@1700000000", true),
    ("@1700000000.5", true),
    ("@17.", false),
    ("@-1", true),
    ("10/Oct/2000:13:55:36 -0700", true),
    ("10/Oct/2000:13:55:36 +0700000", false),
    ("2020-10-12T10:11:12.5+02:00", true),
    ("2020-10-12T10:11:12.5+0200999", false),
    ("2020-W05-3", true),
    ("2020.123", true),
    ("Jan 1 10:30:45 CET", true),
    ("Jan 1 10:30:45 Foo", false),
    ("Jan 1 10.30.45", false),
    ("Sat, 15 Aug 2005 15:52:01 +0000", true),
    ("Monday 15th August 2005", true),
    ("15-Aug-2005", true),
    ("Aug-15-2005", true),
    ("2005-Aug-15", true),
    ("12/22/78", true),
    ("1/2/3", true),
    ("XII 2020", true),
    ("GMT+2", true),
    ("+02:00", true),
    ("+1234567", false),
    ("(CET)", true),
    ("10pm", true),
    ("13pm", false),
    ("10:61", false),
    ("24:00", true),
    ("25:00", false),
    ("x", true),
    ("!", false),
    ("2020x", true),
    ("T10", true),
    ("back of 7pm", true),
    ("weekday", true),
    ("2 weekdays", true),
    ("eighth day", true),
    ("tomorrow!", false),
    ("now\u{a0}", true),
    ("\u{a0}now", true),
    ("UTC+1", true),
    ("z", true),
    ("j", false),
    ("10:00 j", false),
];

#[test]
fn accepts_what_php_accepts() {
    for (datetime, accepted) in CASES {
        assert_eq!(
            accepts(datetime),
            Some(*accepted),
            "date_create({datetime:?})"
        );
    }
}

#[test]
fn leaves_database_dependent_zones_undecided() {
    for datetime in [
        "Zulu",
        "Japan",
        "Europe/Copenhagen",
        "2020-10-12 America/New_York",
    ] {
        assert_eq!(accepts(datetime), None, "date_create({datetime:?})");
    }
}

#[test]
fn a_later_error_settles_an_undecided_zone() {
    assert_eq!(accepts("Japan 4 qm"), Some(false));
}
